56	+
57	+/** Issues the right document for the guest: the only place that knows which kind of guest gets which document. */
58	+public final class DocumentFactory {
59	+
60	+    private final DocumentWriter personReceipt = new PersonReceiptWriter();
61	+    private final DocumentWriter companyInvoice = new CompanyInvoiceWriter();
62	+    private final DocumentWriter foreignReceipt = new ForeignReceiptWriter();
63	+
64	+    public ReservationReceipt issue(Reservation reservation, Room room) {
65	+        DocumentWriter writer = writerFor(reservation.guest());
66	+        return new ReservationReceipt(writer.title(), reservation, room, writer.text(reservation, room));
67	+    }
68	+
69	+    private DocumentWriter writerFor(Guest guest) {
70	+        if (guest.isCompany()) {
71	+            return companyInvoice;
72	+        }
73	+        if (guest.isForeigner()) {
74	+            return foreignReceipt;
75	+        }
76	+        return personReceipt;
77	+    }
78	+}
