+        service.confirm(reservation.id());
+        return reservation;
+    }
+
+    private Reservation bookAndPay(Guest guest) {
+        return bookAndPay(guest, 201, "2027-03-10", "2027-03-12", RatePlan.STANDARD);
+    }
+
+    @Test
+    void aCompanyGetsAnInvoiceWithTheWithheldTax() {
