  1	package hotel.reservations;
  2	
  3	import hotel.documents.DocumentFactory;
  4	import hotel.documents.ReservationReceipt;
  5	import hotel.messages.EmailSender;
  6	import hotel.rooms.Room;
  7	import hotel.rooms.Rooms;
  8	import java.math.BigDecimal;
  9	
 10	/** The life of a reservation: created, confirmed (paid), checked in, checked out, or cancelled. */
 11	public final class ReservationService {
 12	
 13	    static final String HOTEL_NAME = "Pousada Maré Alta";
 14	
 15	    private final Rooms rooms;
 16	    private final ReservationStore store;
 17	    private final PriceCalculator priceCalculator;
 18	    private final EmailSender emailSender;
 19	    private final DocumentFactory documents = new DocumentFactory();
 20	
 21	    public ReservationService(
 22	            Rooms rooms, ReservationStore store, PriceCalculator priceCalculator, EmailSender emailSender) {
 23	        this.rooms = rooms;
 24	        this.store = store;
 25	        this.priceCalculator = priceCalculator;
 26	        this.emailSender = emailSender;
 27	    }
 28	
 29	    public synchronized Reservation create(NewReservation request) {
 30	        if (!request.checkOut().isAfter(request.checkIn())) {
 31	            throw new HotelException(ErrorCode.INVALID_REQUEST, "check-out must be after check-in");
 32	        }
 33	        if (request.guests() < 1) {
 34	            throw new HotelException(ErrorCode.INVALID_REQUEST, "a reservation needs at least one guest");
 35	        }
 36	        Room room = rooms.find(request.roomNumber())
 37	                .orElseThrow(() -> new HotelException(
 38	                        ErrorCode.ROOM_NOT_FOUND, "room " + request.roomNumber() + " does not exist"));
 39	        if (request.guests() > room.capacity()) {
 40	            throw new HotelException(
 41	                    ErrorCode.CAPACITY_EXCEEDED,
 42	                    "room " + room.number() + " takes at most " + room.capacity() + " guests");
 43	        }
 44	        if (store.isRoomTaken(room.number(), request.checkIn(), request.checkOut())) {
 45	            throw new HotelException(
 46	                    ErrorCode.ROOM_UNAVAILABLE, "room " + room.number() + " is taken on some of those nights");
 47	        }
 48	        Price price = priceCalculator.calculate(room, request.checkIn(), request.checkOut(), request.ratePlan());
 49	        return store.add(request, price);
 50	    }
 51	
 52	    public Reservation find(long reservationId) {
 53	        return store.find(reservationId)
 54	                .orElseThrow(() -> new HotelException(
 55	                        ErrorCode.RESERVATION_NOT_FOUND, "reservation " + reservationId + " does not exist"));
 56	    }
 57	
 58	    /** The guest paid: the reservation is confirmed and the guest gets the receipt by e-mail. */
 59	    public synchronized Reservation confirm(long reservationId) {
 60	        Reservation reservation = find(reservationId);
 61	        if (reservation.status() != ReservationStatus.PENDING) {
 62	            throw notAllowed(reservation, "confirm");
 63	        }
 64	        reservation.confirmPayment();
 65	        store.update(reservation);
 66	        ReservationReceipt receipt = documents.issue(reservation, roomOf(reservation));
 67	        emailSender.send(
 68	                reservation.guest().email(),
 69	                "Reserva confirmada - " + HOTEL_NAME,
 70	                confirmationEmailBody(reservation, receipt));
 71	        return reservation;
 72	    }
 73	
 74	    /**
 75	     * Cancelling before the stay starts. What was paid comes back according to the rate plan (a pending
 76	     * reservation was never paid, so nothing comes back).
 77	     */
 78	    public synchronized Reservation cancel(long reservationId) {
 79	        Reservation reservation = find(reservationId);
 80	        if (reservation.status() != ReservationStatus.PENDING
 81	                && reservation.status() != ReservationStatus.CONFIRMED) {
 82	            throw notAllowed(reservation, "cancel");
 83	        }
 84	        BigDecimal refund = switch (reservation.ratePlan()) {
 85	            case STANDARD -> reservation.amountPaid();
 86	            case NON_REFUNDABLE -> PriceCalculator.cents(BigDecimal.ZERO);
 87	        };
 88	        reservation.cancel(refund);
 89	        store.update(reservation);
 90	        return reservation;
 91	    }
 92	
 93	    public synchronized Reservation checkIn(long reservationId) {
 94	        Reservation reservation = find(reservationId);
 95	        if (reservation.status() != ReservationStatus.CONFIRMED) {
 96	            throw notAllowed(reservation, "check in");
 97	        }
 98	        reservation.changeStatus(ReservationStatus.CHECKED_IN);
 99	        store.update(reservation);
100	        return reservation;
101	    }
102	
103	    /** The guest leaves: the stay is closed and the final receipt is handed over. */
104	    public synchronized ReservationReceipt checkOut(long reservationId) {
105	        Reservation reservation = find(reservationId);
106	        if (reservation.status() != ReservationStatus.CHECKED_IN) {
107	            throw notAllowed(reservation, "check out");
108	        }
109	        reservation.changeStatus(ReservationStatus.CHECKED_OUT);
110	        store.update(reservation);
111	        return documents.issue(reservation, roomOf(reservation));
112	    }
113	
114	    /** A copy of the receipt, for a guest who lost it. Only paid reservations have one. */
115	    public ReservationReceipt receiptCopy(long reservationId) {
116	        Reservation reservation = find(reservationId);
117	        if (!reservation.isPaid()) {
118	            throw notAllowed(reservation, "issue a receipt for");
119	        }
120	        return documents.issue(reservation, roomOf(reservation));
121	    }
122	
123	    private Room roomOf(Reservation reservation) {
124	        return rooms.find(reservation.roomNumber()).orElseThrow();
125	    }
126	
127	    private static String confirmationEmailBody(Reservation reservation, ReservationReceipt receipt) {
128	        return "Olá, " + reservation.guest().name() + "!\n\n"
129	                + "Sua reserva na " + HOTEL_NAME + " está confirmada. Estes são os dados dela:\n\n"
130	                + receipt.text() + "\n"
131	                + "A entrada é a partir das 14h, e a saída, até as 12h.\n"
132	                + "Até breve!\n";
133	    }
134	
135	    private static HotelException notAllowed(Reservation reservation, String operation) {
136	        return new HotelException(
137	                ErrorCode.OPERATION_NOT_ALLOWED,
138	                "cannot " + operation + " reservation " + reservation.id() + " while it is " + reservation.status());
139	    }
140	}
